using Microsoft.AspNetCore.Mvc;using Microsoft.EntityFrameworkCore;
[ApiController,Route("api/products")]
public sealed class ProductsController(EComDbContext db):ControllerBase
{
 [HttpGet]public async Task<IActionResult> GetProducts([FromQuery]string? search=null,[FromQuery]long? categoryId=null,CancellationToken ct=default){var q=db.Products.AsNoTracking().Include(x=>x.Images).Where(x=>x.IsActive&&!x.IsDeleted);if(!string.IsNullOrWhiteSpace(search)){var s=search.Trim().ToLower();q=q.Where(x=>x.Name.ToLower().Contains(s)||(x.Description!=null&&x.Description.ToLower().Contains(s)));}if(categoryId.HasValue)q=q.Where(x=>x.CategoryId==categoryId.Value);return Ok(await q.OrderByDescending(x=>x.CreatedAt).Select(x=>new{x.Id,x.CategoryId,x.Name,x.Sku,x.Description,x.Price,x.CompareAtPrice,x.StockQuantity,category=x.Category.Name,images=x.Images.OrderBy(i=>i.DisplayOrder).Select(i=>i.Url).ToList()}).ToListAsync(ct));}
 [HttpGet("{id:long}")]public async Task<IActionResult> GetProduct(long id,CancellationToken ct){var p=await db.Products.AsNoTracking().Include(x=>x.Category).Include(x=>x.Images).Where(x=>x.Id==id&&x.IsActive&&!x.IsDeleted).Select(x=>new{x.Id,x.CategoryId,x.Name,x.Sku,x.Description,x.Price,x.CompareAtPrice,x.StockQuantity,category=x.Category.Name,images=x.Images.OrderBy(i=>i.DisplayOrder).Select(i=>i.Url).ToList()}).SingleOrDefaultAsync(ct);return p is null?NotFound():Ok(p);}
}
